async function main() {
  console.log('=====================================================================');
  console.log('BẮT ĐẦU TẠO BỘ TÀI NGUYÊN NÂNG CẤP HOÀN HẢO THEO PHẢN HỒI (V6)');
  console.log('=====================================================================');

  // 1. Tạo file HTML
  const posterAppHtml = generatePosterAppHtml();
  const profileCrmHtml = generateProfileCrmHtml();
  const slideDeckHtml = generateSlideDeckHtml();
  const printDeckHtml = generatePrintableDeckHtml();

  const posterAppPath = path.join(DOC_DIR, 'POSTER_APP_CEO1983_3D.html');
  const profileCrmPath = path.join(DOC_DIR, 'PROFILE_CRM_QUAN_TRI_CEO1983.html');
  const slideDeckPath = path.join(DOC_DIR, 'SLIDE_TONG_THE_HE_SINH_THAI_CEO1983.html');
  const printDeckPath = path.join(DOC_DIR, 'SLIDE_TONG_THE_HE_SINH_THAI_CEO1983_PRINT.html');

  fs.writeFileSync(posterAppPath, posterAppHtml, 'utf8');
  fs.writeFileSync(profileCrmPath, profileCrmHtml, 'utf8');
  fs.writeFileSync(slideDeckPath, slideDeckHtml, 'utf8');
  fs.writeFileSync(printDeckPath, printDeckHtml, 'utf8');

  console.log('✓ Đã ghi các tệp HTML nguồn.');

  // 2. Render chất lượng cao qua Playwright
  console.log('>>> Đang mở trình duyệt để xuất PDF và PNG siêu nét...');
  const browser = await chromium.launch({
    executablePath: 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe',
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });

  // Xuất POSTER APP 3D (PNG nét căng + PDF)
  console.log('>>> [1/3] Xuất Poster App CEO 1983 (Ultra HD)...');
  const pagePoster = await browser.newPage({
    viewport: { width: 1400, height: 1980 },
    deviceScaleFactor: 2.0 // Tăng độ sắc nét lên gấp đôi
  });
  await pagePoster.setContent(posterAppHtml, { waitUntil: 'networkidle' });
  await pagePoster.waitForTimeout(1000);

  const posterPngPath = path.join(DOC_DIR, 'POSTER_APP_CEO1983_3D.png');
  const posterPdfPath = path.join(DOC_DIR, 'POSTER_APP_CEO1983_3D.pdf');
  await pagePoster.screenshot({ path: posterPngPath, fullPage: true });
  await pagePoster.pdf({
    path: posterPdfPath,
    width: '1400px',
    height: '1980px',
    printBackground: true,
    margin: { top: 0, right: 0, bottom: 0, left: 0 }
  });
  await pagePoster.close();
  console.log('✓ Đã xuất POSTER_APP_CEO1983_3D.png & .pdf');

  // Xuất PROFILE CRM 3D (PNG nét căng + PDF)
  console.log('>>> [2/3] Xuất Profile CRM Quản Trị (Showroom 3D Ultra HD)...');
  const pageProfile = await browser.newPage({
    viewport: { width: 1920, height: 1080 },
    deviceScaleFactor: 2.0 // Tăng độ sắc nét
  });
  await pageProfile.setContent(profileCrmHtml, { waitUntil: 'networkidle' });
  await pageProfile.waitForTimeout(1000);

  const profilePngPath = path.join(DOC_DIR, 'PROFILE_CRM_QUAN_TRI_CEO1983.png');
  const profilePdfPath = path.join(DOC_DIR, 'PROFILE_CRM_QUAN_TRI_CEO1983.pdf');
  await pageProfile.screenshot({ path: profilePngPath, fullPage: true });
  await pageProfile.pdf({
    path: profilePdfPath,
    width: '1920px',
    height: '1080px',
    printBackground: true,
    margin: { top: 0, right: 0, bottom: 0, left: 0 }
  });
  await pageProfile.close();
  console.log('✓ Đã xuất PROFILE_CRM_QUAN_TRI_CEO1983.png & .pdf');

  // Xuất SLIDE TỔNG THỂ 10 SLIDE (PDF 16:9 Vector nguyên bản)
  console.log('>>> [3/3] Xuất Slide Tổng Thể Hệ Sinh Thái (10 trang 16:9 PDF)...');
  const pageSlide = await browser.newPage({
    viewport: { width: 1440, height: 810 },
    deviceScaleFactor: 1.5
  });
  await pageSlide.setContent(printDeckHtml, { waitUntil: 'networkidle' });
  await pageSlide.waitForTimeout(1000);

  const slidePdfPath = path.join(DOC_DIR, 'SLIDE_TONG_THE_HE_SINH_THAI_CEO1983.pdf');
  await pageSlide.pdf({
    path: slidePdfPath,
    width: '1440px',
    height: '810px',
    printBackground: true,
    margin: { top: 0, right: 0, bottom: 0, left: 0 }
  });
  await pageSlide.close();
  console.log('✓ Đã xuất SLIDE_TONG_THE_HE_SINH_THAI_CEO1983.pdf');

  await browser.close();

  // Dọn dẹp file tạm print
  if (fs.existsSync(printDeckPath)) fs.unlinkSync(printDeckPath);

  console.log('=====================================================================');
  console.log('HOÀN TẤT XUẤT BẢN TOÀN BỘ TÀI NGUYÊN NÂNG CẤP CHUẨN XỊN V6!');
  console.log('=====================================================================');
}

main().catch(err => {
  console.error('LỖI KHI XUẤT BẢN:', err);
  process.exit(1);
});
